export const ComponentAttrs = {
	id: '',
	classList: '',
	style: '',
	innerHTML: ''
}

/**
 * Represents a base class of all components generated by js in this app
 */
export default class Component {
	/** Represents HTML element where created object will be appended @type {HTMLElement} */
	#context;
	#attrs;

	/** Created by Component base class HTMLElement @type {HTMLElement}*/
	HTMLElement;

	/**
	 * 
	 * @param {HTMLElement} context HTML element where created object will be appended
	 * @param {Object} attrs Component attributes
	 * @param {string} element All available HTML tags (div, span, button, img and etc.)
	 */
	constructor(context, attrs, element = null) {
		this.#context = context;
		this.#attrs = attrs;

		this.#init(element);
	}

	#init(element) {
		this.HTMLElement = document.createElement(element ?? 'div');

		for (const key in this.#attrs) {
			if (this.#attrs[key] != '') {
				this.HTMLElement[key] = this.#attrs[key];
			}
		}

		this.#context.appendChild(this.HTMLElement);
	}

	/** Initialize inner HTML elements @abstract */
	initElementContent() { }

	/** Initialize elements events @abstract */
	initElementEvents() { }

	/**
	 * Add event listener to HTML element by type
	 * @param {string} type Event type (click, mouseup, change and etc.)
	 * @param {Function} callback Event action
	 */
	setEvent(type, callback) {
		this.HTMLElement.addEventListener(type, callback);
	}
}